


/** A stock-keeping unit that inventory quantities are tracked against. Catalog variants reference an inventory item rather than carrying their own counter. */ export type InventoryItemInput = { /** Optional searchable barcode. */ "barcode"?: string; /** Time the inventory item was created. Format: date-time. */ "created_at": string | globalThis.Date; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Stable inventory item ID. */ "inventory_item_id": string; /** Caller-owned metadata. */ "metadata": Record<string, string>; /** Merchant-facing inventory item name. */ "name": string; /** Optional searchable stock-keeping unit. */ "sku"?: string; /** Current inventory item lifecycle status. */ "status": "active" | "inactive" | "archived"; /** Time the inventory item last changed. Format: date-time. */ "updated_at": string | globalThis.Date; /** Optimistic-concurrency version for item writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
